@ExtendWith(RestDocumentationExtension.class)
@WebMvcTest(controllers = OrderController.class)
class OrderControllerDocsTest {

    private MockMvc mockMvc;

    @MockBean
    private OrderService orderService;

    @BeforeEach
    void setUp(WebApplicationContext context,
               RestDocumentationContextProvider provider) {
        this.mockMvc = MockMvcBuilders.webAppContextSetup(context)
                .apply(documentationConfiguration(provider))
                .build();
    }

    @DisplayName("신규 주문을 등록하는 API")
    @Test
    void createOrder() throws Exception {
        // given
        given(orderService.createOrder(any(), any()))
                .willReturn(OrderResponse.builder()
                        .id(1L).totalPrice(8500).build());

        // when & then
        mockMvc.perform(post("/api/v1/orders/new")
                        .content(objectMapper.writeValueAsString(
                                new OrderCreateRequest(List.of("001", "002"))))
                        .contentType(APPLICATION_JSON))
                .andExpect(status().isOk())
                .andDo(document("order-create",
                        preprocessRequest(prettyPrint()),
                        preprocessResponse(prettyPrint()),
                        requestFields(
                                fieldWithPath("productNumbers").type(ARRAY)
                                        .description("상품 번호 목록")
                        ),
                        responseFields(
                                fieldWithPath("code").type(NUMBER).description("코드"),
                                fieldWithPath("status").type(STRING).description("상태"),
                                fieldWithPath("message").type(STRING).description("메시지"),
                                fieldWithPath("data.id").type(NUMBER).description("주문 ID"),
                                fieldWithPath("data.totalPrice").type(NUMBER)
                                        .description("주문 총 금액")
                        )
                ));
    }
}
